// Generated bytes only. Check cooperative I/O bounds, token lifetime and the
// crypto chunk boundary independently of the end-to-end import checkpoints.
#include "wwhd/cancel.h"
#include "wwhd/disc_crypto.h"
#include "wwhd/file_io.h"
#include "wwhd/sha256.h"

#include <algorithm>
#include <cstdio>
#include <streambuf>
#include <thread>

namespace {
void require(bool condition, const char* message) {
    if (!condition)
        throw std::runtime_error(message);
}
template<class F> void expect_cancel(F call) {
    try {
        call();
    } catch (const wwhd::Cancelled&) {
        return;
    }
    throw std::runtime_error("expected distinct Cancelled exception");
}

class CancellingInput : public std::streambuf {
  public:
    explicit CancellingInput(std::atomic<bool>& flag) : flag_(flag) {}
    unsigned reads = 0;
    std::streamsize xsgetn(char* data, std::streamsize count) override {
        require(count > 0 && count <= 65536, "read exceeded 64 KiB cancellation boundary");
        ++reads;
        std::fill_n(data, size_t(count), 'x');
        flag_ = true;
        return count;
    }
  private:
    std::atomic<bool>& flag_;
};

void run() {
    using namespace wwhd;
    std::atomic<bool> flag{false};
    {
        CancellationScope scope(&flag);
        CancellingInput buffer(flag);
        std::istream input(&buffer);
        Bytes bytes(3 * 65536);
        expect_cancel([&] { read_exact(input, bytes.data(), bytes.size(), "short read"); });
        require(buffer.reads == 1, "read continued after token was set");
        expect_cancel([&] { disc_aes_cbc_decrypt({}, {}, bytes); });
        expect_cancel([&] { disc_sha1(bytes); });
        {
            CancellationScope nested(nullptr);
            check_cancel();
        }
        expect_cancel([] { check_cancel(); });
        bool separate = false;
        std::thread other([&] { separate = !cancellation_requested() && import_cancel == nullptr; });
        other.join();
        require(separate, "unrelated thread inherited a cancelled import");
    }
    check_cancel();
    require(import_cancel == nullptr, "cancelled token escaped its scope");

    // Two complete 64 KiB chunks plus one AES block. Expected values were
    // calculated independently with Python hashlib and PyCryptodome. Every
    // ciphertext block equals the initial IV, so every plaintext block agrees.
    Bytes encrypted(131088);
    DiscKey iv{};
    for (size_t i = 0; i < iv.size(); ++i) iv[i] = uint8_t(i);
    for (size_t i = 0; i < encrypted.size(); ++i) encrypted[i] = uint8_t(i % 16);
    const DiscKey expected{0x49,0x59,0x84,0xa1,0x88,0x3b,0x79,0xea,0x77,0xc1,0xf7,0x31,0x16,0x01,0x1e,0x9d};
    const Bytes plain = disc_aes_cbc_decrypt({}, iv, encrypted);
    require(plain.size() == encrypted.size(), "CBC result size");
    for (size_t i = 0; i < plain.size(); ++i)
        require(plain[i] == expected[i % 16], "CBC chaining changed at a chunk boundary");
    const Bytes zeros(encrypted.size());
    const DiscSha1 sha1{0x8f,0x87,0x34,0x0b,0xee,0x38,0x6b,0x4a,0x53,0x38,
                       0xdc,0x0c,0xe0,0x40,0x0c,0x0e,0xa6,0x2a,0xcf,0xf1};
    require(disc_sha1(zeros) == sha1, "chunked SHA-1 differs from hashlib");
    Sha256 sha256;
    sha256.update(zeros.data(), zeros.size());
    require(sha256.hex() == "123189eb6f425840c2fb4b3b4dca5b3a1382217e0d8c9b110fb3d98c4aab7140",
            "cancellable SHA-256 differs from hashlib");
}
} // namespace

int main() {
    try {
        run();
        std::puts("Cancellation scopes, bounded reads and multi-chunk crypto passed");
    } catch (const std::exception& ex) {
        std::fprintf(stderr, "%s\n", ex.what());
        return 1;
    }
}
